from autor import Lectie, Unitate, grafic

REF = "Manual Art Klett, clasa a VI-a (manuale.edu.ro), lecția „{}”"
S_UNESCO = ["UNESCO World Heritage Centre – lista patrimoniului mondial (whc.unesco.org)", "Ministerul Culturii – Monumente UNESCO din România"]
S_UE = ["Uniunea Europeană – Țările UE (european-union.europa.eu)", "Consiliul UE – statele membre"]
S_HDI = ["UNDP – Human Development Report 2025", "Wikipedia – List of countries by Human Development Index"]
S_ERASMUS = ["Comisia Europeană – Erasmus+ (erasmus-plus.ec.europa.eu)", "Agenția Națională pentru Programe Comunitare (ANPCDEFP) – Erasmus+"]


def unitate():
    # ================================================================ S32 Valori culturale și umane europene
    V = Lectie(6, "VI-S32-valori-culturale-umane-europene", "Valori culturale și umane europene",
               "Ce ne leagă pe noi, europenii, dincolo de granițe?",
               [("Valori comune", "Europenii împărtășesc valori precum demnitatea umană, libertatea, democrația, egalitatea, statul de drept și respectarea drepturilor omului. Aceste valori sunt scrise și în tratatele Uniunii Europene.\nMotto-ul UE este „Unită în diversitate”: țările își păstrează limbile și tradițiile, dar colaborează."),
                ("Patrimoniul cultural", "Europa are un patrimoniu foarte bogat: monumente antice (Acropole, Colosseum), catedrale gotice, castele, orașe istorice, muzee celebre (Luvru, Prado, Ermitaj).\nRomânia are în patrimoniul mondial UNESCO, printre altele: Delta Dunării, bisericile pictate din nordul Moldovei, bisericile de lemn din Maramureș, satele cu biserici fortificate din Transilvania, centrul istoric al Sighișoarei, Mănăstirea Horezu, cetățile dacice din Munții Orăștiei, peisajul minier de la Roșia Montană."),
                ("Simboluri și oameni", "Simbolurile UE: drapelul albastru cu 12 stele aurii, imnul „Oda bucuriei” (din Simfonia a IX-a de Beethoven), Ziua Europei pe 9 mai, moneda euro.\nEuropa a dat lumii mari artiști, savanți și scriitori. Printre români: George Enescu (muzică), Constantin Brâncuși (sculptură), Mihai Eminescu (poezie), Henri Coandă (aviație).")],
               stiaica="Cele 12 stele de pe drapelul Uniunii Europene nu reprezintă numărul de state: cifra 12 e un simbol al perfecțiunii și al unității.",
               ref=REF.format("Valori culturale și umane europene"))
    V.a(1, "1.2", "Care e motto-ul Uniunii Europene?", "„Unită în diversitate”", ["„Toți la fel”", "„Fiecare pentru el”", "„O singură limbă”"], "Diversitatea e respectată în UE.")
    V.a(2, "1.2", "Câte stele are drapelul Uniunii Europene?", "12", ["27", "50", "7"], "Numărul 12 simbolizează unitatea, nu numărul de state.", surse=S_UE)
    V.a(2, "1.2", "Ce imn are Uniunea Europeană?", "„Oda bucuriei”, din Simfonia a IX-a de Beethoven", ["„Deșteaptă-te, române!”", "„La Marseillaise”", "un cântec pop"], "Imnul european nu are versuri oficiale.", surse=S_UE)
    V.a(2, "1.2", "Când se sărbătorește Ziua Europei?", "pe 9 mai", ["pe 1 decembrie", "pe 1 iunie", "pe 25 decembrie"], "Pe 9 mai 1950 a fost propusă cooperarea care a dus la UE.", surse=S_UE)
    V.s(2, "3.4", "Asociază monumentul UNESCO din România cu regiunea.", [("bisericile pictate", "nordul Moldovei (Bucovina)"), ("bisericile de lemn", "Maramureș"), ("cetățile dacice", "Munții Orăștiei"), ("centrul istoric medieval", "Sighișoara")], "Patrimoniul UNESCO al României.", surse=S_UNESCO)
    V.s(2, "3.4", "Asociază personalitatea română cu domeniul.", [("George Enescu", "muzică"), ("Constantin Brâncuși", "sculptură"), ("Mihai Eminescu", "poezie"), ("Henri Coandă", "aviație")], "Români care au contribuit la cultura europeană.")
    V.a(2, "3.4", "Ce rezervație naturală din România e în patrimoniul UNESCO?", "Delta Dunării", ["Lacul Snagov", "Parcul Herăstrău", "Muntele Tâmpa"], "Delta Dunării e patrimoniu natural mondial din 1991.", surse=S_UNESCO)
    V.a(2, "3.4", "Ce mănăstire din Bucovina e cunoscută pentru „albastrul de Voroneț”?", "Mănăstirea Voroneț", ["Mănăstirea Horezu", "Mănăstirea Curtea de Argeș", "Mănăstirea Cozia"], "Voroneț face parte din bisericile pictate din Moldova.", surse=S_UNESCO)
    V.a(2, "3.4", "Ce sculptor român a creat „Coloana fără sfârșit” de la Târgu Jiu?", "Constantin Brâncuși", ["George Enescu", "Nicolae Grigorescu", "Ion Creangă"], "Ansamblul de la Târgu Jiu include și „Masa tăcerii” și „Poarta sărutului”.")
    V.a(2, "1.2", "Ce valori împărtășesc statele Uniunii Europene?", "democrația, libertatea, egalitatea, respectarea drepturilor omului", ["conducerea de către un singur om", "o singură religie obligatorie", "interzicerea călătoriilor"], "Aceste valori sunt înscrise în tratatele UE.", surse=S_UE)
    V.a(2, "4.3", "Ce înseamnă patrimoniu cultural?", "monumentele, tradițiile, operele de artă moștenite de la înaintași și păstrate pentru viitor", ["banii unei țări", "fabricile noi", "drumurile de azi"], "Patrimoniul ne arată istoria și identitatea.")
    V.a(2, "4.3", "Ce înseamnă patrimoniu imaterial?", "tradiții, obiceiuri, muzică, dansuri, meșteșuguri transmise din generație în generație", ["clădiri vechi", "munți și râuri", "bani"], "Exemple din România: Călușul, doina, colindatul în ceată bărbătească, ceramica de Horezu.")
    V.a(2, "3.4", "Ce dans tradițional românesc e în patrimoniul imaterial UNESCO?", "Călușul", ["Tango", "Flamenco", "Valsul vienez"], "Ritualul Călușului a fost înscris în 2005 (inițial ca Capodoperă).", surse=S_UNESCO)
    V.p(2, "3.4", "Atinge pe harta României Sighișoara, cetate medievală din patrimoniul UNESCO.", "romania", 46.22, 24.79, "Sighișoara", 40, "Sighișoara e în județul Mureș, pe Târnava Mare.", surse=S_UNESCO)
    V.p(3, "3.4", "Atinge pe harta României Maramureșul, cu bisericile de lemn din patrimoniul UNESCO.", "romania", 47.7, 24, "Maramureș", 60, "Maramureșul e în nordul României.", surse=S_UNESCO)
    V.adev(2, "1.2", "Statele UE trebuie să renunțe la limbile și tradițiile lor.", False, "Fals: UE are 24 de limbi oficiale și respectă tradițiile fiecărei țări.")
    V.adev(2, "3.4", "Bisericile pictate din nordul Moldovei sunt în patrimoniul mondial UNESCO.", True, "Adevărat: au fost înscrise în 1993.", surse=S_UNESCO)
    V.l(2, "1.2", "Completează.", "Ziua Europei se sărbătorește pe [9 mai]; drapelul UE are [12] stele aurii.", ["1 decembrie", "27"], "9 mai, 12 stele.", surse=S_UE)
    V.l(2, "3.4", "Completează.", "„Coloana fără sfârșit” a fost realizată de [Brâncuși], iar „Rapsodiile române” de [Enescu].", ["Eminescu", "Coandă"], "Brâncuși și Enescu.")
    V.a(2, "3.4", "Ce oraș european are muzeul Prado?", "Madrid", ["Paris", "Londra", "Berlin"], "Prado e unul dintre cele mai mari muzee de artă.")
    V.a(2, "3.4", "Ce monument antic simbolizează Atena?", "Acropole, cu Partenonul", ["Colosseumul", "Turnul din Pisa", "Big Ben"], "Atena e considerată leagănul democrației.")
    V.a(3, "1.2", "De ce Grecia antică e numită „leagănul democrației”?", "pentru că în Atena cetățenii votau deciziile importante", ["pentru că avea cei mai mulți regi", "pentru că a inventat euro", "pentru că avea cele mai mari armate"], "Democrație = conducerea poporului.")
    V.a(2, "4.3", "Ce poți face pentru a păstra patrimoniul local?", "vizitezi cu respect monumentele, nu scrii pe ziduri, înveți despre tradiții", ["iei pietre de la monumente", "scrii pe pereți", "arunci gunoaie lângă ele"], "Patrimoniul se păstrează prin respect.")
    V.a(2, "3.3", "Câte limbi oficiale are Uniunea Europeană?", "24", ["1", "27", "100"], "Toate documentele oficiale importante se traduc.", surse=S_UE)
    V.a(2, "4.3", "Ce program european le permite elevilor și studenților să studieze în alte țări?", "Erasmus+", ["Schengen", "Euro", "Apollo"], "Erasmus+ finanțează schimburi de elevi, studenți și profesori.", surse=S_ERASMUS)
    V.a(2, "1.2", "Ce înseamnă spațiul Schengen?", "un grup de țări europene între care oamenii circulă fără controale la granițe", ["o monedă", "un munte", "un program de televiziune"], "România face parte integral din spațiul Schengen din 2025.", surse=["Consiliul UE, decizia din 12.12.2024 – ridicarea controalelor la frontierele terestre cu România și Bulgaria", "Comisia Europeană – Schengen Area"])
    V.g(3, "2.3 4.1", "Graficul arată numărul de vizitatori la trei muzee imaginare într-un an. Care e cel mai vizitat?", grafic("bare", "Vizitatori într-un an (muzee imaginare)", [("muzeul A", 8), ("muzeul B", 3), ("muzeul C", 5)], "milioane"), "muzeul A", ["muzeul B", "muzeul C", "sunt egale"], "8 milioane de vizitatori la muzeul A.")
    V.a(3, "3.4", "Ce leagă peisajul minier de la Roșia Montană de istoria Europei?", "galerii romane de aur, de aproape 2 000 de ani, unice în lume", ["un vulcan activ", "o centrală nucleară", "o stațiune de schi"], "A fost înscris în patrimoniul UNESCO în 2021.", surse=S_UNESCO)
    V.a(2, "3.4", "Ce ceramică tradițională românească e în patrimoniul imaterial UNESCO?", "ceramica de Horezu", ["porțelanul de Meissen", "faianța olandeză", "sticla de Murano"], "Meșteșugul ceramicii de Horezu a fost înscris în 2012.", surse=S_UNESCO)
    V.a(2, "1.2", "Cum se numește instituția UE aleasă direct de cetățeni?", "Parlamentul European", ["Banca Mondială", "ONU", "NATO"], "Alegerile europene au loc o dată la 5 ani.", surse=S_UE)

    # ================================================================ S33 Calitatea vieții în Europa
    Q = Lectie(6, "VI-S33-calitatea-vietii-europa", "Calitatea vieții în Europa",
               "Ce face ca oamenii să trăiască bine într-o țară?",
               [("Ce înseamnă calitatea vieții", "Calitatea vieții arată cât de bine trăiesc oamenii: veniturile, locuința, sănătatea, educația, mediul curat, siguranța, timpul liber și relațiile cu ceilalți.\nONU măsoară dezvoltarea țărilor prin Indicele Dezvoltării Umane (IDU), care combină speranța de viață, educația și venitul. Multe țări europene au un IDU foarte ridicat."),
                ("Diferențe în Europa", "În general, nordul și vestul Europei (Norvegia, Elveția, Danemarca, Țările de Jos, Islanda) au venituri mari, servicii publice bune și mediu curat. În estul și sud-estul Europei veniturile sunt mai mici, dar cresc.\nȘi în interiorul unei țări există diferențe între orașele mari și zonele rurale."),
                ("Factori și soluții", "Calitatea vieții crește prin: educație pentru toți, spitale bune, transport public, aer și apă curate, spații verzi, locuri de muncă.\nFiecare dintre noi contribuie: prin respect, implicare în comunitate și grijă pentru mediu.")],
               stiaica="Speranța de viață la naștere în țările Uniunii Europene trece de 80 de ani, după Eurostat; e una dintre cele mai mari din lume.",
               ref=REF.format("Calitatea vieții în Europa"))
    Q.a(1, "1.2", "Ce înseamnă calitatea vieții?", "cât de bine trăiesc oamenii: sănătate, educație, venit, mediu, siguranță", ["cât de mare e o țară", "câți munți are", "câte mașini are fiecare om"], "Calitatea vieții are mai multe componente.")
    Q.a(2, "1.2", "Ce combină Indicele Dezvoltării Umane (IDU)?", "speranța de viață, educația și venitul", ["suprafața și relieful", "numărul de orașe", "înălțimea munților"], "IDU e calculat de ONU (UNDP).", surse=S_HDI)
    Q.a(2, "3.3", "Ce țări europene au de obicei cel mai mare IDU?", "Norvegia, Elveția, Islanda, Danemarca", ["Belarus, Moldova", "Albania, Kosovo", "Ucraina, Georgia"], "Țările nordice și Elveția au IDU foarte ridicat.", surse=S_HDI)
    Q.a(2, "1.2", "Ce este speranța de viață?", "numărul mediu de ani pe care se așteaptă să-i trăiască un om", ["vârsta de pensionare", "vârsta la care începe școala", "numărul de copii dintr-o familie"], "Speranța de viață crește cu sănătatea și condițiile de trai.")
    Q.a(2, "3.3", "Cât e, aproximativ, speranța de viață în Uniunea Europeană?", "peste 80 de ani", ["40 de ani", "60 de ani", "120 de ani"], "După Eurostat, speranța de viață în UE e de aproximativ 81 de ani.", surse=["Eurostat – Mortality and life expectancy statistics", "OMS – Life expectancy at birth"])
    Q.s(2, "3.3", "Asociază factorul cu efectul asupra calității vieții.", [("spitale bune", "oameni mai sănătoși"), ("școli bune", "locuri de muncă mai bune"), ("aer curat", "mai puține boli respiratorii"), ("transport public", "mai puțin trafic și poluare")], "Fiecare factor contează.")
    Q.a(2, "3.3", "Ce poate scădea calitatea vieții într-un oraș mare?", "poluarea, traficul și prețul mare al locuințelor", ["parcurile", "bibliotecile", "pistele de biciclete"], "Orașele mari au avantaje, dar și probleme.")
    Q.a(2, "3.3", "De ce în zonele rurale calitatea vieții poate fi mai scăzută?", "pentru că sunt mai puține servicii: spitale, școli, transport, locuri de muncă", ["pentru că aerul e mai poluat", "pentru că e prea mult trafic", "pentru că sunt prea multe muzee"], "Dar satele au aer curat și liniște.")
    Q.a(2, "4.3", "Compară viața la sat cu cea la oraș.", "la oraș sunt mai multe servicii; la sat e aer mai curat și mai multă liniște", ["la sat sunt mai multe spitale", "la oraș e mai liniște", "sunt identice"], "Fiecare are avantaje și dezavantaje.")
    Q.p(2, "3.3", "Atinge pe hartă Norvegia, una dintre țările cu cel mai mare IDU.", "lume", 62, 9, "Norvegia", 500, "Norvegia e în nordul Europei.", surse=S_HDI)
    Q.p(3, "3.3", "Atinge pe hartă Elveția.", "lume", 46.8, 8.2, "Elveția", 200, "Elveția e în Alpi.")
    Q.adev(2, "1.2", "Calitatea vieții depinde doar de bani.", False, "Fals: contează și sănătatea, educația, mediul, siguranța, relațiile.")
    Q.adev(2, "3.3", "Există diferențe de calitate a vieții și în interiorul aceleiași țări.", True, "Adevărat: de exemplu, între orașele mari și satele izolate.")
    Q.l(2, "1.2", "Completează.", "Indicele Dezvoltării Umane combină speranța de [viață], educația și [venitul].", ["vacanță", "relieful"], "Viață și venit.", surse=S_HDI)
    Q.l(2, "3.3", "Completează.", "Parcurile și grădinile din oraș se numesc spații [verzi]; ele fac aerul mai [curat].", ["gri", "poluat"], "Spații verzi.")
    Q.g(3, "2.3 4.1", "Graficul arată speranța de viață în trei țări imaginare. Unde oamenii trăiesc, în medie, cel mai mult?", grafic("bare", "Speranța de viață (țări imaginare)", [("țara A", 76), ("țara B", 83), ("țara C", 79)], "ani"), "în țara B", ["în țara A", "în țara C", "egal"], "83 de ani în țara B.")
    Q.a(2, "4.3", "Cum poate o școală să îmbunătățească calitatea vieții elevilor?", "spații verzi, sport, mese sănătoase, ateliere și o atmosferă de respect", ["mai puține pauze", "fără ferestre", "fără bibliotecă"], "Școala e o parte importantă a vieții.")
    Q.a(2, "3.3", "Ce înseamnă siguranța într-o comunitate?", "oamenii se pot plimba liniștiți, fără să se teamă de violență sau accidente", ["să nu ieși niciodată din casă", "să nu ai vecini", "să ai cât mai multe garduri"], "Siguranța e o parte a calității vieții.")
    Q.a(2, "3.4", "Ce înseamnă accesibilitatea clădirilor?", "clădirile pot fi folosite de toți, inclusiv de persoanele în scaun rulant", ["clădirile sunt foarte înalte", "clădirile nu au uși", "clădirile sunt doar pentru turiști"], "Rampele, liftul și ușile largi ajută pe toată lumea.")
    Q.a(3, "1.2", "De ce mulți tineri din Europa de Est lucrează în Europa de Vest?", "pentru salarii mai mari și alte oportunități", ["pentru că în est nu există școli", "pentru că în vest e mai cald", "pentru că e obligatoriu"], "Migrația pentru muncă e frecventă în UE.")
    Q.a(3, "4.3", "Ce poate face o comunitate ca tinerii să rămână acasă?", "locuri de muncă, școli bune, spații de joacă și sport, internet rapid", ["închiderea școlilor", "tăierea parcurilor", "mai puține autobuze"], "Comunitățile atractive își păstrează tinerii.")
    Q.a(2, "3.3", "Ce rol au voluntarii într-o comunitate?", "ajută gratuit la acțiuni utile: ecologizări, sprijin pentru vârstnici, evenimente", ["primesc salarii mari", "nu au niciun rol", "închid parcurile"], "Voluntariatul crește calitatea vieții tuturor.")
    Q.a(2, "4.3", "Ce înseamnă un oraș „verde”?", "un oraș cu parcuri, transport curat, reciclare și clădiri care economisesc energie", ["un oraș vopsit în verde", "un oraș fără copaci", "un oraș plin de mașini"], "Orașele verzi sunt mai sănătoase.")
    Q.a(2, "3.3", "Ce serviciu public e esențial pentru sănătate?", "sistemul de sănătate (spitale, medici de familie, vaccinare)", ["cinematograful", "magazinul de jucării", "parcarea"], "Sănătatea e o componentă de bază a calității vieții.")
    Q.a(3, "3.3", "De ce educația crește calitatea vieții?", "oamenii educați găsesc mai ușor locuri de muncă bune și iau decizii mai informate", ["nu are legătură", "scade veniturile", "face oamenii mai puțin sănătoși"], "Educația deschide oportunități.")
    Q.d(2, "3.3", "Ce țară nordică, cu calitate ridicată a vieții, e marcată pe hartă?", "lume", 56, 10, "Danemarca", ["Germania", "Polonia", "Țările de Jos"], "Danemarca e pe Peninsula Iutlanda și pe insule.")
    Q.a(2, "4.3", "Ce poți face tu pentru calitatea vieții în cartierul tău?", "păstrezi curățenia, respecți vecinii, participi la acțiuni comunitare", ["faci zgomot noaptea", "arunci gunoaie", "strici băncile din parc"], "Fiecare contribuie.")
    Q.a(3, "1.2", "Ce înseamnă „egalitate de șanse”?", "toți copiii au acces la educație și servicii, indiferent de unde provin", ["toți au aceleași note", "toți locuiesc în același oraș", "toți au aceeași meserie"], "Egalitatea de șanse reduce diferențele.")
    Q.a(2, "3.3", "Ce înseamnă „speranță de viață mare”?", "oamenii trăiesc mult, de obicei datorită sănătății și condițiilor bune", ["oamenii speră să călătorească", "se nasc mulți copii", "oamenii se mută des"], "Speranța de viață e un indicator al calității vieții.")
    Q.a(2, "3.4", "Ce instituție UE sprijină regiunile mai puțin dezvoltate prin fonduri?", "Uniunea Europeană, prin fondurile europene", ["FIFA", "NASA", "UNESCO"], "Fondurile europene construiesc drumuri, școli, spitale.", surse=S_UE)

    return Unitate(6, "u4-europa-contemporana.json", "Europa în lumea contemporană").add(V, Q)
